function workRepositoriesCommand() {
  return new Command().description(
    "Read what every bound source repository declares about itself, and account for each.\nWork spanning more than one repository is shaped from the centre, where the rules\neach repository writes for itself \u2014 its own agent instructions and the skills\ninstalled only there \u2014 are invisible. This shows them without leaving the centre.\nFraming approval and Wayfinder finish stay shut until every one is read or\nexplicitly declared untouched."
  ).arguments("[id:string]").option("-t, --target <path:string>", "Knowledge repository or bound leaf.", { default: "." }).option("--read <repository:string>", "Record that this repository was read on its own terms.").option("--note <text:string>", "With --read: what its own rules require of this work.").option("--untouched <repository:string>", "Record that this work does not touch it.").option("--reason <text:string>", "With --untouched: why it is not touched.").option("--json", "Print machine-readable JSON.").action(async (options, id) => {
    const named2 = options.read ?? options.untouched;
    if (named2) {
      const result2 = await accountWorkRepository({
        target: options.target,
        ...id ? { id } : {},
        repository: named2,
        ...options.read ? { note: options.note ?? "" } : {},
        ...options.untouched ? { untouched: options.reason ?? "" } : {}
      });
      if (options.json) printJson(result2);
      else {
        process.stdout.write(
          result2.status === "read" ? `${result2.repository} is accounted for: read on its own terms.
` : `${result2.repository} is accounted for: this work does not touch it.
`
        );
      }
      return;
    }
    const result = await readWorkRepositories(options.target, id);
    if (options.json) {
      printJson(result);
      return;
    }
    if (result.repositories.length === 0) {
      process.stdout.write(
        `${result.id} binds no source repository, so there is nothing here to account for.
`
      );
      return;
    }
    for (const entry of result.repositories) {
      process.stdout.write(`
=== ${entry.repository}
${entry.root}
`);
      if (entry.unreadable) {
        process.stdout.write(`Cannot be read right now: ${entry.unreadable}
`);
        continue;
      }
      if (entry.instructions) {
        process.stdout.write(
          `
Its own instructions (${entry.instructionsPath}, ${entry.instructions.split("\n").length} lines):

${entry.instructions}
`
        );
      } else {
        process.stdout.write("\nIt states no rules of its own.\n");
      }
      if (entry.skills.length > 0) {
        process.stdout.write(`
Skills installed only here (${entry.skills.length}):
`);
        for (const skill of entry.skills) {
          process.stdout.write(`  ${skill.name} \u2014 ${skill.description || "(no description)"}
`);
        }
      }
      if (!entry.accounted) {
        process.stdout.write("\nNot accounted for in this bundle yet.\n");
      } else if (entry.accounted.status === "untouched") {
        process.stdout.write(`
Declared untouched: ${entry.accounted.reason}
`);
      } else {
        process.stdout.write(`
Read: ${entry.accounted.note}
`);
        if (entry.stale) {
          process.stdout.write(
            "This repository changed its own rules after that was recorded, so the\nreceipt describes something that is no longer there. Read it again.\n"
          );
        }
      }
    }
  });
}
function workDecisionsCommand() {
  return new Command().description(
    "Account for what this work decided, and where each decision now lives.\nA maintainer answers a product question once and the answer is recorded verbatim;\nwithout this the bundle archives with it, curated knowledge stays empty of\ndecisions, and the next bundle asks them the same question again. Nothing here\nasks them anything: it records where their answer went."
  ).arguments("[id:string]").option("-t, --target <path:string>", "Knowledge repository or bound leaf.", { default: "." }).option("--what <text:string>", "The decision, in the words the product uses.").option("--said <where:string>", "Where the maintainer said it: a map issue, or the framing.").option("--promoted <concept:string>", "It became this decision of its own.").option("--folded <concept:string>", "This concept now carries it.").option("--not-durable", "It outlives nothing beyond this work.").option("--none <why:string>", "This work settled nothing that outlives it, and why.").option("--reason <text:string>", "With --not-durable: why it outlives nothing.").option("--json", "Print machine-readable JSON.").action(async (options, id) => {
    if (options.none) {
      const result2 = await recordWorkDecision({
        target: options.target,
        ...id ? { id } : {},
        none: options.none,
        what: "",
        said: "",
        disposition: "none"
      });
      if (options.json) printJson(result2);
      else {
        process.stdout.write(
          "Recorded: this work settled nothing that outlives it.\n"
        );
      }
      return;
    }
    if (options.what) {
      const disposition = options.promoted ? "promoted" : options.folded ? "folded" : "not-durable";
      const result2 = await recordWorkDecision({
        target: options.target,
        ...id ? { id } : {},
        what: options.what,
        said: options.said ?? "",
        disposition,
        ...options.promoted ? { into: options.promoted } : {},
        ...options.folded ? { into: options.folded } : {},
        ...options.reason ? { reason: options.reason } : {}
      });
      if (options.json) printJson(result2);
      else process.stdout.write(`Recorded as ${result2.disposition}: ${result2.what}
`);
      return;
    }
    const result = await readWorkDecisions(options.target, id);
    if (options.json) {
      printJson(result);
      return;
    }
    if (result.recorded.length === 0) {
      process.stdout.write("Nothing is accounted for yet.\n");
    }
    for (const entry of result.recorded) {
      process.stdout.write(
        `
${String(entry.what)}
  said: ${String(entry.said)}
  ${String(entry.disposition)}${entry.into ? `: ${String(entry.into)}` : ""}${entry.reason ? ` \u2014 ${String(entry.reason)}` : ""}
`
      );
    }
    if (result.unaccounted.length > 0) {
      process.stdout.write(
        `
${result.unaccounted.length} answer(s) the map recorded reach nothing yet:
`
      );
      for (const entry of result.unaccounted) {
        process.stdout.write(`
  ${entry.issue} \u2014 ${entry.title}
    ${entry.summary}
`);
      }
      process.stdout.write(
        "\nThese are already the maintainer's words. Deciding where each belongs is yours;\nasking them again is not.\n"
      );
    }
    if (result.issues.length > 0) {
      process.stdout.write("\nClosure is blocked by:\n");
      for (const issue3 of result.issues) process.stdout.write(`  - ${issue3}
`);
      process.exitCode = 2;
    }
  });
}
